CREATE TABLE public.beagu_2026_official_school_profiles(school_id text PRIMARY KEY,disclosure_code text UNIQUE,source_year smallint,profile jsonb,teacher_total int);
GRANT SELECT ON public.beagu_2026_official_school_profiles TO service_role;
UPDATE public.beagu_lv1_school_sort_index SET student_count=CASE school_id WHEN 'T000001' THEN 900 WHEN 'T000002' THEN 100 WHEN 'T000003' THEN 50 END,student_reference_year=2024,male_teacher_ratio=CASE school_id WHEN 'T000001' THEN 80 WHEN 'T000002' THEN 5 WHEN 'T000003' THEN 40 END,junior_teacher_ratio=CASE school_id WHEN 'T000001' THEN 80 WHEN 'T000002' THEN 5 WHEN 'T000003' THEN 40 END;
